-- Name: Bus Images Dashboard NPS - Syed
-- Source: Syed Athena Saved Queries export
-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

WITH NPS AS ( SELECT DISTINCT DATE(DATE_ADD('MINUTE', 330, a.received_on)) AS ReceivedOn, a.survey_id AS SurveyId, a.redbus_userid AS rb_user_id, -- CASE WHEN a.question_option_id = 17 THEN 0 ELSE a.question_option_id END AS NPS_Score, CASE WHEN a.question_option_id IN (17, 1, 2, 3, 4, 5, 6, 0) THEN 'Detractors' WHEN a.question_option_id IN (7, 8) THEN 'Neutrals' WHEN a.question_option_id IN (9, 10) THEN 'Promoters' END AS NPS_Type, CASE WHEN a.survey_id = 9 THEN 'Booking' WHEN a.survey_id = 1 THEN 'Travel' ELSE 'Cancellation' END AS Survey_Type, -- a.email, -- a.mobile_number AS mobilenumber, a.order_number AS ordernumber, a.business_unit AS businessunit, a.feedback, a.channel, n.operator_id AS bo_id, n.service_provider_name AS bo_name, -- c.survey_info, n.selected_language, CASE WHEN n.operator_id IN ( 10283, 16081, 6392, 15447, 8065, 15129, 7115, 10244, 10823, 15130, 11060, 15499, 11044, 3030, 15443, 16124, 16227, 2020, 16374, 16426, 16580, 16647, 16777, 17012, 16884, 4040, 17137, 17101, 17889, 18115, 18101, 18237, 18491, 19393, 19502, 22837, 22875, 22878, 24978, 25187, 25946, 27000, 26936, 27455, 28011, 29176, 29479, 29391, 29392, 32000, 32272, 32245, 34300, 34400, 33740, 35303, 35268, 33000) THEN 'RTC' ELSE 'Pvt' END AS RTC, n.user_type, n.route_id, -- CASE WHEN (n.source_location_id, n.destination_location_id) IN (SELECT src_id, dest_id FROM "lis"."short_route_sds") THEN 'Short Route' ELSE 'Long Route' END AS route_cohort n.date_of_issue AS bookingtime, n.date_of_journey, n.boarding_time -- COALESCE(CAST(bc.time_of_event AS VARCHAR), 'Not Cancelled') AS cancellationtime, -- COALESCE(bc.cancellation_type, 'Not Cancelled') AS cancellationtype FROM "ugc"."nps_survey_response" AS a -- LEFT JOIN "ugc"."nps_survey_info_response" AS c -- ON a.key = c.key LEFT JOIN "transaction"."bus_ticket_events" AS n ON a.order_number = n.tin -- LEFT JOIN "transaction"."bus_cancellation_events" AS bc -- ON a.order_number = bc.tin WHERE a.received_on >= TIMESTAMP '2026-04-30 18:30:00' AND a.received_on < TIMESTAMP '2026-06-07 18:30:00' AND n.time_of_event >= TIMESTAMP '2026-04-30 18:30:00' AND n.time_of_event < TIMESTAMP '2026-06-07 18:30:00' AND a.question_option_id <> -1 AND a.business_unit = 1 AND a.country_code = 1 AND n.country_code = 'IND' AND n.route_id IN ( SELECT DISTINCT CAST(route_id_train_no AS BIGINT) FROM "user_interaction"."ui_ux_events" WHERE __time >= TIMESTAMP '2026-05-31 18:30:00' AND __time < TIMESTAMP '2026-06-01 18:30:00' AND event_src IN ('iOS') AND event_group IN ('sl_screen_load', 'ab_exp_busImage', 'ab_exp_imagesGalleryLoaded', 'ab_exp_imagesSectionLoaded') AND event_name IN ('NewBusImageLoaded')) -- AND bc.country_code = 'IND' -- ORDER BY ReceivedOn ) SELECT ReceivedOn, channel, Survey_Type, CASE WHEN ReceivedOn >= DATE '2026-05-01' AND ReceivedOn < DATE '2026-05-19' THEN 'Pre' ELSE CAST(ReceivedOn AS VARCHAR) END AS time_period, COUNT(DISTINCT CASE WHEN NPS_Type = 'Promoters' THEN (ReceivedOn, rb_user_id) END) AS Promoters_nps_received, COUNT(DISTINCT CASE WHEN NPS_Type = 'Neutrals' THEN (ReceivedOn, rb_user_id) END) AS Neutrals_nps_received, COUNT(DISTINCT CASE WHEN NPS_Type = 'Detractors' THEN (ReceivedOn, rb_user_id) END) AS Detractors_nps_received, COUNT(DISTINCT (ReceivedOn, rb_user_id)) Overall_nps_received FROM NPS GROUP BY 1, 2, 3, 4 ORDER BY 1, 2, 3
